color.text { $default: #172132, theme.dark: #f7f8fa }
color.action { $default: #005198, theme.dark: #83c9ff }
color.border: #c8ced8
color.alphaProbe: #ff000080
font.family: Arial
font.size.heading: 28
font.size.body { $default: 16, accessibility.large-text: 20 }
font.weight.regular: 400
font.weight.bold: 700
spacing.pad { $default: 24, density.compact: 12 }
spacing.gap: 12
spacing.sm: 8
radius.card: 12
radius.button: 8
typography.body: { fontFamily: font.family, fontSize: font.size.body, fontWeight: font.weight.regular }
surface.card: { fills: [ color.surface ], radius: radius.card }
